import os
from pathlib import Path
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from django.http import FileResponse, Http404
from django.conf import settings


class DocumentRetrievalView(APIView):
    """Serves documents from the configured document store.
    Documents are organized by tenant_id/category/filename.
    """
    permission_classes = [IsAuthenticated]

    ALLOWED_EXTENSIONS = ('.pdf', '.docx', '.xlsx', '.txt', '.csv')
    BASE_DOCUMENT_PATH = getattr(settings, 'DOCUMENT_STORE_PATH', '/app/documents')

    def get(self, request, tenant_id, category, filename):
        # Validate file extension
        ext = os.path.splitext(filename)[1].lower()
        if ext not in self.ALLOWED_EXTENSIONS:
            return Response(
                {'error': 'File type not permitted'},
                status=400
            )

        # Construct the file path
        relative_path = os.path.join(str(tenant_id), category, filename)
        file_path = os.path.join(self.BASE_DOCUMENT_PATH, relative_path)

        # Check file exists
        if not os.path.isfile(file_path):
            raise Http404("Document not found")

        # Serve the file
        try:
            response = FileResponse(
                open(file_path, 'rb'),
                content_type=self._get_content_type(ext)
            )
            response['Content-Disposition'] = f'attachment; filename="{filename}"'
            return response
        except PermissionError:
            return Response(
                {'error': 'Access denied to requested resource'},
                status=403
            )

    def _get_content_type(self, ext):
        content_types = {
            '.pdf': 'application/pdf',
            '.docx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
            '.xlsx': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            '.txt': 'text/plain',
            '.csv': 'text/csv',
        }
        return content_types.get(ext, 'application/octet-stream')


class DocumentListView(APIView):
    """Lists available documents for a tenant."""
    permission_classes = [IsAuthenticated]

    BASE_DOCUMENT_PATH = getattr(settings, 'DOCUMENT_STORE_PATH', '/app/documents')

    def get(self, request, tenant_id):
        tenant_path = os.path.join(self.BASE_DOCUMENT_PATH, str(tenant_id))

        if not os.path.isdir(tenant_path):
            return Response({'documents': []})

        documents = []
        for root, dirs, files in os.walk(tenant_path):
            for f in files:
                full_path = os.path.join(root, f)
                rel = os.path.relpath(full_path, tenant_path)
                documents.append({
                    'path': rel,
                    'size': os.path.getsize(full_path),
                    'name': f
                })

        return Response({'documents': documents})


